function decodeFrames({ width, count, data }) {
  const input = Uint8Array.from(globalThis.atob(data), (character) => character.charCodeAt(0));
  const previous = Array(width).fill(0);
  const frames = [];
  let offset = 0;
  const read = () => {
    let value = 0;
    let factor = 1;
    for (let index = 0; index < 5; index += 1) {
      if (offset >= input.length) throw new Error('Truncated demonstration frame pack');
      const byte = input[offset++];
      value += (byte & 0x7f) * factor;
      if (!(byte & 0x80)) return value % 2 ? -(value + 1) / 2 : value / 2;
      factor *= 128;
    }
    throw new Error('Oversized demonstration frame varint');
  };
  for (let row = 0; row < count; row += 1) {
    const frame = [];
    for (let channel = 0; channel < width; channel += 1) {
      previous[channel] += read();
      frame.push(previous[channel]);
    }
    frames.push(frame);
  }
  if (offset !== input.length) throw new Error('Trailing demonstration frame bytes');
  return frames;
}

export const WORLD_DEMONSTRATIONS = PACKED_WORLD_DEMONSTRATIONS.map(
  ({ beforeProof, beforeFrames, framePack, afterFrames, afterProof }) => ({
    ...beforeProof,
    proof: { ...beforeFrames, frames: decodeFrames(framePack), ...afterFrames },
    ...afterProof,
  }),
);
